css:
.pod-root {
  --bg-base: var(--pn-06060c, #06060c);
  --bg-surface: var(--pn-ffffff-0035, rgba(255, 255, 255, 0.035));
  --bg-surface-elevated: var(--pn-ffffff-006, rgba(255, 255, 255, 0.06));
  --border-subtle: var(--pn-ffffff-008, rgba(255, 255, 255, 0.08));
  --border-accent: rgba(var(--pod-accent-rgb, 168,85,247), 0.35);
  --text-primary: var(--pn-ffffff, #ffffff);
  --text-secondary: var(--pn-ffffff-07, rgba(255, 255, 255, 0.7));
  --text-muted: var(--pn-ffffff-045, rgba(255, 255, 255, 0.45));
  --accent-theme: var(--pod-accent, #a855f7);
  --accent-theme-glow: rgba(var(--pod-accent-rgb, 168,85,247), 0.35);
  --accent-cyan: #38bdf8;
  --accent-green: #34d399;
  --accent-amber: #fbbf24;
  --accent-rose: #fb7185;
  --card-radius: 20px;
}

/* 테마 변형 */
.pod-root .theme-obsidian {
  --accent-theme: #94a3b8;
  --accent-theme-glow: rgba(148, 163, 184, 0.35);
  --border-accent: rgba(148, 163, 184, 0.3);
}
.pod-root .theme-emerald {
  --accent-theme: #10b981;
  --accent-theme-glow: rgba(16, 185, 129, 0.35);
  --border-accent: rgba(16, 185, 129, 0.3);
}

.pod-root * {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  font-family: 'Pretendard', -apple-system, BlinkMacSystemFont, sans-serif;
}

.pod-root {
  background: var(--bg-base);
  color: var(--text-primary);
  min-height: 100vh;
  overflow-x: hidden;
  display: flex;
  flex-direction: column;
  position: relative;
}

.pod-root .bg-aurora {
  position: fixed;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 100vw;
  max-width: 1400px;
  height: 600px;
  background: radial-gradient(circle at 50% 10%, var(--accent-theme-glow) 0%, rgba(56, 189, 248, 0.06) 40%, transparent 70%);
  pointer-events: none;
  z-index: 0;
  filter: blur(80px);
  transition: background 0.5s ease;
}

/* ── 헤더 ── */
.pod-root header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--pn-06060c-088, rgba(6, 6, 12, 0.88));
  backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--border-subtle);
  padding: 12px 24px 12px 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.pod-root .brand-group {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
}

.pod-root .brand-logo-img {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  object-fit: cover;
  box-shadow: 0 0 16px var(--accent-theme-glow);
}

.pod-root .brand-name-wrap {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.pod-root .brand-title {
  font-family: 'Montserrat', sans-serif;
  font-size: 18px;
  font-weight: 900;
  color: var(--pn-ffffff, #fff);
  letter-spacing: -0.02em;
}

.pod-root .brand-badge {
  font-size: 10px;
  font-weight: 800;
  padding: 2px 7px;
  border-radius: 99px;
  background: var(--pn-ffffff-006, rgba(255, 255, 255, 0.06));
  border: 1px solid var(--border-accent);
  color: var(--accent-theme);
  letter-spacing: 0.05em;
}

/* 탭 컨트롤 네비게이션 */
.pod-root .view-tabs {
  display: flex;
  align-items: center;
  background: var(--pn-ffffff-004, rgba(255, 255, 255, 0.04));
  border: 1px solid var(--border-subtle);
  border-radius: 14px;
  padding: 4px;
  gap: 4px;
}

.pod-root .view-tab {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border-radius: 10px;
  background: transparent;
  border: none;
  color: var(--text-secondary);
  font-size: 13.5px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;
}

.pod-root .view-tab:hover {
  color: var(--pn-ffffff, #fff);
  background: var(--pn-ffffff-005, rgba(255, 255, 255, 0.05));
}

.pod-root .view-tab.active {
  background: var(--pn-ffffff-01, rgba(255, 255, 255, 0.1));
  border: 1px solid var(--border-accent);
  color: var(--pn-ffffff, #fff);
  font-weight: 700;
  box-shadow: 0 4px 15px var(--accent-theme-glow);
}

/* 헤더 우측 액션 */
.pod-root .header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

/* 테마 스위처 칩 */
.pod-root .theme-switcher-bar {
  display: flex;
  align-items: center;
  gap: 4px;
  background: var(--pn-ffffff-003, rgba(255, 255, 255, 0.03));
  border: 1px solid var(--border-subtle);
  border-radius: 99px;
  padding: 3px 6px;
}

.pod-root .theme-btn-dot {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 1px solid transparent;
  cursor: pointer;
  transition: all 0.2s;
}

.pod-root .theme-btn-dot:hover { transform: scale(1.2); }
.pod-root .theme-btn-dot.active { border-color: var(--pn-ffffff, #fff); box-shadow: 0 0 8px currentColor; }
.pod-root .theme-dot-violet { background: #c084fc; color: var(--pod-accent, #a855f7); }
.pod-root .theme-dot-obsidian { background: #94a3b8; color: #64748b; }
.pod-root .theme-dot-emerald { background: #34d399; color: #10b981; }

.pod-root .save-indicator {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11.5px;
  color: var(--text-muted);
  font-weight: 600;
  padding: 6px 10px;
  border-radius: 99px;
  background: var(--pn-ffffff-003, rgba(255, 255, 255, 0.03));
}

.pod-root .save-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent-green);
  box-shadow: 0 0 8px var(--accent-green);
}

.pod-root .btn-action-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 11px;
  background: var(--pn-ffffff-005, rgba(255, 255, 255, 0.05));
  border: 1px solid var(--border-subtle);
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.2s;
}

.pod-root .btn-action-icon:hover {
  color: var(--pn-ffffff, #fff);
  background: var(--pn-ffffff-01, rgba(255, 255, 255, 0.1));
  border-color: var(--pn-ffffff-02, rgba(255, 255, 255, 0.2));
}

.pod-root .btn-cta-nav {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  border-radius: 11px;
  background: linear-gradient(135deg, var(--accent-theme) 0%, #6366f1 100%);
  color: #fff;
  font-size: 12.5px;
  font-weight: 700;
  text-decoration: none;
  box-shadow: 0 4px 15px var(--accent-theme-glow);
  transition: all 0.2s;
}

.pod-root .btn-cta-nav:hover {
  transform: translateY(-1px);
}

/* ── 메인 컨테이너 ── */
.pod-root main {
  position: relative;
  z-index: 1;
  max-width: 1320px;
  width: 100%;
  margin: 0 auto;
  padding: 28px 24px 80px;
  flex: 1;
}

/* ── 킬러 기능 1: 깃허브 잔디 스타일 스트릭 히트맵 ── */
.pod-root .heatmap-hero-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--card-radius);
  padding: 20px 24px;
  margin-bottom: 24px;
  backdrop-filter: blur(16px);
  position: relative;
  overflow: hidden;
}

.pod-root .heatmap-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 14px;
}

.pod-root .streak-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  border-radius: 99px;
  background: rgba(249, 115, 22, 0.12);
  border: 1px solid rgba(249, 115, 22, 0.35);
  color: var(--pt-fdba74, #fdba74);
  font-size: 12.5px;
  font-weight: 800;
}

.pod-root .heatmap-stats {
  display: flex;
  align-items: center;
  gap: 18px;
  font-size: 12.5px;
  color: var(--text-secondary);
}

.pod-root .heatmap-stats strong {
  color: var(--pn-ffffff, #fff);
  font-family: 'Montserrat', sans-serif;
  font-size: 14px;
}

.pod-root .heatmap-grid-scroll {
  overflow-x: auto;
  padding-bottom: 6px;
}

.pod-root .heatmap-grid {
  display: grid;
  grid-template-rows: repeat(7, 12px);
  grid-auto-flow: column;
  gap: 3px;
  width: max-content;
}

.pod-root .heatmap-cell {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  background: var(--pn-ffffff-004, rgba(255, 255, 255, 0.04));
  cursor: pointer;
  transition: transform 0.15s, background 0.2s;
}

.pod-root .heatmap-cell:hover {
  transform: scale(1.35);
  z-index: 10;
  border: 1px solid var(--pn-ffffff, #fff);
}

.pod-root .heatmap-cell.level-1 { background: rgba(var(--pod-accent-rgb, 168,85,247), 0.3); }
.pod-root .heatmap-cell.level-2 { background: rgba(var(--pod-accent-rgb, 168,85,247), 0.6); }
.pod-root .heatmap-cell.level-3 { background: var(--pod-accent, #a855f7); box-shadow: 0 0 6px var(--pod-accent, #a855f7); }
.pod-root .heatmap-cell.level-4 { background: #38bdf8; box-shadow: 0 0 8px #38bdf8; }

/* ── 공통 카드 스타일 ── */
.pod-root .panel-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--card-radius);
  padding: 24px;
  backdrop-filter: blur(16px);
  transition: border-color 0.2s ease;
}

.pod-root .panel-card:hover {
  border-color: var(--pn-ffffff-014, rgba(255, 255, 255, 0.14));
}

.pod-root .panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
  gap: 12px;
}

.pod-root .panel-title-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
}

.pod-root .panel-icon-box {
  width: 32px;
  height: 32px;
  border-radius: 10px;
  background: var(--pn-ffffff-006, rgba(255, 255, 255, 0.06));
  border: 1px solid var(--border-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-theme);
}

.pod-root .panel-title {
  font-size: 18px;
  font-weight: 800;
  color: var(--pn-ffffff, #fff);
}

.pod-root .panel-subtitle {
  font-size: 13px;
  color: var(--text-muted);
  margin-top: 2px;
}

/* 인풋 공통 */
.pod-root .input-field {
  width: 100%;
  background: var(--pn-000000-035, rgba(0, 0, 0, 0.35));
  border: 1px solid var(--pn-ffffff-01, rgba(255, 255, 255, 0.1));
  border-radius: 12px;
  padding: 12px 16px;
  color: var(--pn-ffffff, #fff);
  font-size: 14px;
  outline: none;
  transition: all 0.2s ease;
}

.pod-root .input-field:focus {
  border-color: var(--accent-theme);
  box-shadow: 0 0 15px var(--accent-theme-glow);
  background: var(--pn-000000-05, rgba(0, 0, 0, 0.5));
}

.pod-root textarea.input-field {
  resize: vertical;
  min-height: 70px;
  line-height: 1.5;
}

/* =========================================================
   TAB 1. LIFE COMPASS
   ========================================================= */
.pod-root #tabCompassView {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.pod-root .hero-banner-compass {
  background: linear-gradient(135deg, var(--accent-theme-glow) 0%, rgba(56, 189, 248, 0.06) 100%);
  border: 1px solid var(--border-accent);
  border-radius: var(--card-radius);
  padding: 36px 32px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.pod-root .compass-year-badge {
  font-family: 'Montserrat', sans-serif;
  font-size: 12px;
  font-weight: 900;
  color: var(--accent-theme);
  letter-spacing: 0.15em;
  text-transform: uppercase;
  margin-bottom: 8px;
}

.pod-root .compass-headline {
  font-size: 26px;
  font-weight: 900;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
  background: linear-gradient(135deg, var(--pn-ffffff, #fff) 0%, var(--pn-e2e8f0, #e2e8f0) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.pod-root .theme-of-year-box {
  max-width: 780px;
  margin: 20px auto 0;
}

.pod-root .theme-input {
  font-size: 17px;
  font-weight: 700;
  text-align: center;
  padding: 16px 20px;
  background: var(--pn-000000-045, rgba(0, 0, 0, 0.45));
  border: 1.5px solid var(--border-accent);
  color: var(--pn-ffffff, #fff);
  border-radius: 16px;
  box-shadow: 0 8px 30px var(--pn-000000-05, rgba(0, 0, 0, 0.5));
}

/* 5대 핵심 영역 그리드 */
.pod-root .areas-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
  gap: 20px;
}

.pod-root .area-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--card-radius);
  padding: 22px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  position: relative;
  overflow: hidden;
}

.pod-root .area-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--area-gradient, linear-gradient(90deg, var(--pod-accent, #a855f7), #6366f1));
}

.pod-root .area-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.pod-root .area-code {
  font-family: 'Montserrat', sans-serif;
  font-size: 11px;
  font-weight: 800;
  color: var(--text-muted);
  letter-spacing: 0.1em;
}

.pod-root .area-title-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
}

.pod-root .area-title {
  font-size: 16px;
  font-weight: 800;
  color: var(--pn-ffffff, #fff);
}

.pod-root .field-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.pod-root .field-label {
  font-size: 11.5px;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  display: flex;
  align-items: center;
  gap: 5px;
}

/* =========================================================
   TAB 2. BIG ROCKS & PROJECT TRACKER
   ========================================================= */
.pod-root #tabProjectsView {
  display: none;
  flex-direction: column;
  gap: 24px;
}

.pod-root .quarter-control-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 16px;
  padding: 10px 16px;
}

.pod-root .quarter-tabs {
  display: flex;
  gap: 6px;
}

.pod-root .quarter-pill {
  padding: 8px 18px;
  border-radius: 10px;
  background: transparent;
  border: 1px solid transparent;
  color: var(--text-secondary);
  font-family: 'Montserrat', sans-serif;
  font-size: 13px;
  font-weight: 800;
  cursor: pointer;
  transition: all 0.2s ease;
}

.pod-root .quarter-pill:hover {
  color: var(--pn-ffffff, #fff);
  background: var(--pn-ffffff-005, rgba(255, 255, 255, 0.05));
}

.pod-root .quarter-pill.active {
  background: var(--pn-ffffff-01, rgba(255, 255, 255, 0.1));
  border-color: var(--border-accent);
  color: var(--pn-ffffff, #fff);
  box-shadow: 0 4px 15px var(--accent-theme-glow);
}

.pod-root .quarter-meta {
  display: flex;
  align-items: center;
  gap: 12px;
}

.pod-root .dday-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 800;
  color: var(--pt-38bdf8, #38bdf8);
  background: rgba(56, 189, 248, 0.1);
  border: 1px solid rgba(56, 189, 248, 0.25);
  padding: 5px 12px;
  border-radius: 99px;
}

/* 3대 핵심 목표 (Big Rocks) */
.pod-root .big-rocks-wrap {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 18px;
}

.pod-root .big-rock-card {
  background: var(--pn-000000-035, rgba(0, 0, 0, 0.35));
  border: 1px solid var(--pn-ffffff-009, rgba(255, 255, 255, 0.09));
  border-radius: 16px;
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  position: relative;
}

.pod-root .big-rock-card.completed {
  border-color: rgba(52, 211, 153, 0.4);
  background: rgba(52, 211, 153, 0.04);
}

.pod-root .big-rock-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.pod-root .rock-num-badge {
  font-family: 'Montserrat', sans-serif;
  font-size: 11px;
  font-weight: 900;
  color: var(--accent-theme);
  background: var(--pn-ffffff-008, rgba(255, 255, 255, 0.08));
  padding: 2px 8px;
  border-radius: 6px;
}

.pod-root .rock-checkbox-label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 700;
  color: var(--text-secondary);
  cursor: pointer;
}

.pod-root .rock-checkbox-label input[type="checkbox"] {
  accent-color: var(--accent-green);
  width: 16px;
  height: 16px;
  cursor: pointer;
}

/* 프로젝트 트래커 */
.pod-root .projects-table-wrap {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.pod-root .project-row-item {
  background: var(--pn-000000-035, rgba(0, 0, 0, 0.35));
  border: 1px solid var(--pn-ffffff-008, rgba(255, 255, 255, 0.08));
  border-radius: 16px;
  padding: 16px 20px;
  display: grid;
  grid-template-columns: 2fr 2fr 1.2fr 2fr auto;
  align-items: center;
  gap: 16px;
  transition: all 0.2s ease;
}

.pod-root .project-row-item:hover {
  border-color: var(--pn-ffffff-016, rgba(255, 255, 255, 0.16));
  background: var(--pn-ffffff-002, rgba(255, 255, 255, 0.02));
}

.pod-root .progress-bar-wrap {
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 100%;
}

.pod-root .progress-bar-top {
  display: flex;
  justify-content: space-between;
  font-size: 11.5px;
  font-weight: 700;
  color: var(--text-muted);
}

.pod-root .progress-track {
  width: 100%;
  height: 8px;
  border-radius: 99px;
  background: var(--pn-ffffff-01, rgba(255, 255, 255, 0.1));
  overflow: hidden;
  position: relative;
}

.pod-root .progress-fill {
  height: 100%;
  border-radius: 99px;
  background: linear-gradient(90deg, var(--accent-theme), #38bdf8);
  transition: width 0.3s ease;
}

.pod-root .status-select {
  background: var(--pn-000000-04, rgba(0, 0, 0, 0.4));
  border: 1px solid var(--pn-ffffff-012, rgba(255, 255, 255, 0.12));
  border-radius: 8px;
  padding: 6px 10px;
  color: var(--pn-ffffff, #fff);
  font-size: 12px;
  font-weight: 700;
  outline: none;
  cursor: pointer;
}

.pod-root .btn-del-project {
  background: transparent;
  border: none;
  color: rgba(239, 68, 68, 0.7);
  cursor: pointer;
  padding: 6px;
  border-radius: 6px;
  transition: all 0.2s;
}

.pod-root .btn-del-project:hover {
  color: var(--pt-ef4444, #ef4444);
  background: rgba(239, 68, 68, 0.15);
}

/* 회고 섹션 */
.pod-root .retro-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 16px;
}

.pod-root .retro-card {
  background: var(--pn-000000-03, rgba(0, 0, 0, 0.3));
  border: 1px solid var(--pn-ffffff-008, rgba(255, 255, 255, 0.08));
  border-radius: 14px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.pod-root .retro-label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12.5px;
  font-weight: 800;
}

/* =========================================================
   TAB 3. INTERACTIVE 2026 CALENDAR & DAILY FOCUS
   ========================================================= */
.pod-root #tabCalendarView {
  display: none;
  flex-direction: column;
  gap: 24px;
}

.pod-root .calendar-layout-container {
  display: grid;
  grid-template-columns: 1fr 420px;
  gap: 24px;
  align-items: start;
}

