            { goal: '첫 분기 유료 고객 30명 확보 및 현금흐름 창출', metric: '마케팅 캠페인 및 SNS 릴스 홍보', done: false }
          ],
          projects: [
            { id: 1, name: 'SETUPOD 3D 명함 및 세일즈 퍼널 셋업', deliverable: '온라인 허브 완성 및 주소록 저장 연동', deadline: '2026-03-31', progress: 100, status: 'completed' },
            { id: 2, name: '2026 프로젝트 플래너 디지털 패키지 출시', deliverable: '웹 앱 및 PDF 서식 론칭', deadline: '2026-03-15', progress: 95, status: 'in-progress' },
            { id: 3, name: '첫 분기 유료 고객 30명 확보', deliverable: '마케팅 캠페인 및 콜드 리치', deadline: '2026-03-31', progress: 45, status: 'in-progress' }
          ],
