    // ==========================================
    // 킬러 기능 4: 테마 스킨 스위처
    // ==========================================
    function switchThemeSkin(themeName, btn) {
      plannerState.themeSkin = themeName;
      document.body.classList.remove('theme-obsidian', 'theme-emerald');
      if (themeName !== 'violet') {
        document.body.classList.add(`theme-${themeName}`);
      }
      document.querySelectorAll('.theme-btn-dot').forEach(b => b.classList.remove('active'));
      if (btn) btn.classList.add('active');
      else {
        const targetBtn = document.querySelector(`.theme-dot-${themeName}`);
        if (targetBtn) targetBtn.classList.add('active');
      }
      triggerAutoSave();
