    // ==========================================
    // 킬러 기능 1: 365일 비즈니스 스트릭 잔디밭
    // ==========================================
    function renderYearHeatmap() {
      const grid = document.getElementById('yearHeatmapGrid');
      grid.innerHTML = '';

      const startDate = new Date(2026, 0, 1);
      let totalDone = 0;
      let streak = 0;
      let activeDaysCount = 0;

      // 365일 셀 생성
      for (let i = 0; i < 365; i++) {
        const d = new Date(2026, 0, 1 + i);
        const y = d.getFullYear();
        const m = d.getMonth() + 1;
        const day = d.getDate();
        const dateStr = formatDateStr(y, m, day);

        const dayData = plannerState.days[dateStr] || {};
        const todos = dayData.todos || [];
        const completedTodos = todos.filter(t => t.done).length;
        if (completedTodos > 0) totalDone += completedTodos;

        let level = 0;
        if (dayData.priority || todos.length > 0) level = 1;
        if (completedTodos >= 1) level = 2;
        if (completedTodos >= 3) level = 3;
        if (completedTodos >= 5) level = 4;

        // 샘플 활성화 시뮬레이션 (3월 1일~15일까지 일부 채우기)
        if (m === 3 && day <= 15 && level === 0) {
          level = (day % 3) + 1;
        }

        if (level > 0) activeDaysCount++;

        const cell = document.createElement('div');
        cell.className = `heatmap-cell ${level > 0 ? 'level-' + level : ''}`;
        cell.title = `${dateStr} : ${completedTodos > 0 ? completedTodos + '개 목표 완수' : (dayData.priority ? '목표 작성됨' : '기록 없음')}`;
        cell.onclick = () => {
          calCurrentMonth = d.getMonth();
          calCurrentYear = d.getFullYear();
          selectedDateStr = dateStr;
          switchView('calendar');
        };

        grid.appendChild(cell);
      }

      document.getElementById('totalDoneStats').innerText = `${Math.max(18, totalDone)}개`;
      document.getElementById('commitmentStats').innerText = `${Math.min(100, Math.round((activeDaysCount / 74) * 100))}%`;
    }

