    function renderQuarterView() {
      const q = plannerState.currentQuarter;
      document.getElementById('currentQuarterLabel').innerText = q;
      document.getElementById('retroQuarterLabel').innerText = q;

      const qData = plannerState.quarters[q] || { rocks: [], projects: [], retro: {} };

      // D-Day 계산
      const endDates = { Q1: '2026-03-31', Q2: '2026-06-30', Q3: '2026-09-30', Q4: '2026-12-31' };
      const targetDate = new Date(endDates[q]);
      const today = new Date();
      const diffTime = targetDate - today;
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      const ddayText = diffDays > 0 ? `${q} 마감까지 D-${diffDays}` : (diffDays === 0 ? `${q} 마감일 오늘!` : `${q} 종료`);
      document.getElementById('quarterDdayText').innerText = ddayText;

      // Rocks 바인딩
      for (let i = 1; i <= 3; i++) {
        const rock = qData.rocks[i - 1] || { goal: '', metric: '', done: false };
        const goalInput = document.getElementById(`rockGoal_${i}`);
        const metricInput = document.getElementById(`rockMetric_${i}`);
        const checkInput = document.getElementById(`rockCheck_${i}`);
        const cardEl = document.getElementById(`rockCard_${i}`);

        if (goalInput) goalInput.value = rock.goal || '';
        if (metricInput) metricInput.value = rock.metric || '';
        if (checkInput) checkInput.checked = !!rock.done;
        if (cardEl) {
          if (rock.done) cardEl.classList.add('completed');
          else cardEl.classList.remove('completed');
        }
      }

      // Projects 렌더링
      renderProjectsList(qData.projects || []);

      // Retro 바인딩
      const retro = qData.retro || {};
      document.getElementById('retroKeep').value = retro.keep || '';
      document.getElementById('retroProblem').value = retro.problem || '';
      document.getElementById('retroTry').value = retro.tryAction || '';

      updateQuarterCompletionRate();
      lucide.createIcons();
    }

