      const q = plannerState.currentQuarter;
      if (plannerState.quarters[q].projects[idx]) {
        plannerState.quarters[q].projects[idx].progress = parseInt(val, 10);
        document.getElementById(`projProgLabel_${idx}`).innerText = `${val}%`;
