    function updateQuarterCompletionRate() {
      const q = plannerState.currentQuarter;
      const qData = plannerState.quarters[q];
      if (!qData) return;

      let totalItems = 0;
      let completedItems = 0;

      (qData.rocks || []).forEach(r => {
        totalItems++;
        if (r.done) completedItems++;
      });

      let projProgSum = 0;
      const projects = qData.projects || [];
      if (projects.length > 0) {
        projects.forEach(p => { projProgSum += (p.progress || 0); });
        const avgProj = projProgSum / projects.length;
        const rate = Math.round((completedItems / (totalItems || 1)) * 40 + avgProj * 0.6);
        document.getElementById('quarterCompletionRate').innerText = `${Math.min(100, rate)}%`;
      } else {
        const rate = Math.round((completedItems / (totalItems || 1)) * 100);
        document.getElementById('quarterCompletionRate').innerText = `${rate}%`;
      }
    }

    // ==========================================
    // 3. INTERACTIVE 2026 CALENDAR & DAILY FOCUS
    // ==========================================
    const monthNames = ['1월', '2월', '3월', '4월', '5월', '6월', '7월', '8월', '9월', '10월', '11월', '12월'];

    function renderCalendar() {
      document.getElementById('calYearTitle').innerText = calCurrentYear;
      document.getElementById('calMonthTitle').innerText = monthNames[calCurrentMonth];

      const firstDayOfMonth = new Date(calCurrentYear, calCurrentMonth, 1).getDay();
      const daysInMonth = new Date(calCurrentYear, calCurrentMonth + 1, 0).getDate();
      const daysInPrevMonth = new Date(calCurrentYear, calCurrentMonth, 0).getDate();

      const container = document.getElementById('calDaysGrid');
      container.innerHTML = '';

      for (let i = firstDayOfMonth - 1; i >= 0; i--) {
        const d = daysInPrevMonth - i;
        const cell = document.createElement('div');
        cell.className = 'cal-day-cell other-month';
        cell.innerHTML = `<span class="cal-day-num">${d}</span>`;
        container.appendChild(cell);
      }

      const today = new Date();
      const isCurrentRealMonth = (today.getFullYear() === calCurrentYear && today.getMonth() === calCurrentMonth);
      const realTodayDate = today.getDate();

      for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = formatDateStr(calCurrentYear, calCurrentMonth + 1, d);
        const cell = document.createElement('div');
        cell.className = 'cal-day-cell';
        if (isCurrentRealMonth && d === realTodayDate) cell.classList.add('today');
        if (dateStr === selectedDateStr) cell.classList.add('selected');

        const dayData = plannerState.days[dateStr] || {};
        const todos = dayData.todos || [];
        const dotsHtml = todos.slice(0, 4).map(() => `<span class="cal-todo-dot"></span>`).join('');

        cell.innerHTML = `
          <div style="display:flex;justify-content:space-between;align-items:center;">
            <span class="cal-day-num">${d}</span>
            ${dayData.priority ? '<i data-lucide="flame" style="width:11px;height:11px;color:#f97316;"></i>' : ''}
          </div>
          <div class="cal-day-badges">${dotsHtml}</div>
        `;

        cell.onclick = () => {
          document.querySelectorAll('.cal-day-cell').forEach(c => c.classList.remove('selected'));
          cell.classList.add('selected');
          selectedDateStr = dateStr;
          loadDailyPanel(dateStr);
        };

        container.appendChild(cell);
      }

      lucide.createIcons();
    }

    function changeMonth(delta) {
      calCurrentMonth += delta;
      if (calCurrentMonth > 11) {
        calCurrentMonth = 0;
        calCurrentYear += 1;
      } else if (calCurrentMonth < 0) {
        calCurrentMonth = 11;
        calCurrentYear -= 1;
      }
      renderCalendar();
    }

    function jumpToToday() {
      const now = new Date();
      calCurrentYear = now.getFullYear();
      calCurrentMonth = now.getMonth();
      selectedDateStr = formatDateStr(calCurrentYear, calCurrentMonth + 1, now.getDate());
      renderCalendar();
      loadDailyPanel(selectedDateStr);
    }

    function formatDateStr(y, m, d) {
      const mm = m < 10 ? `0${m}` : m;
      const dd = d < 10 ? `0${d}` : d;
      return `${y}-${mm}-${dd}`;
    }

    function loadDailyPanel(dateStr) {
      const parts = dateStr.split('-');
      const dObj = new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
      const weekDayNames = ['일', '월', '화', '수', '목', '금', '토'];
      const weekDayStr = weekDayNames[dObj.getDay()];

      document.getElementById('selectedDateTitle').innerText = `${parts[0]}년 ${parseInt(parts[1], 10)}월 ${parseInt(parts[2], 10)}일 (${weekDayStr})`;

      const dayData = plannerState.days[dateStr] || { priority: '', todos: [], notes: '' };
      document.getElementById('dailyPriorityInput').value = dayData.priority || '';
      document.getElementById('dailyNotesInput').value = dayData.notes || '';

      renderDailyTodos(dayData.todos || []);
    }

    function renderDailyTodos(todos) {
      const listContainer = document.getElementById('dailyTodoList');
      const doneCount = todos.filter(t => t.done).length;
      document.getElementById('dailyTodoDoneCount').innerText = doneCount;
      document.getElementById('dailyTodoTotalCount').innerText = todos.length;

      if (!todos || todos.length === 0) {
        listContainer.innerHTML = `<div style="font-size:12px;color:var(--text-muted);text-align:center;padding:12px;">오늘의 할 일을 추가해보세요.</div>`;
        return;
      }

      listContainer.innerHTML = todos.map((t, idx) => `
        <div class="todo-item-row ${t.done ? 'done' : ''}">
          <input type="checkbox" class="todo-checkbox" ${t.done ? 'checked' : ''} onchange="toggleTodoDone(${idx})">
          <input type="text" class="todo-text-input" value="${escapeHtml(t.text)}" oninput="updateTodoText(${idx}, this.value)">
          <button class="btn-todo-del" onclick="deleteTodoItem(${idx})">
            <i data-lucide="x" style="width:13px;height:13px;"></i>
          </button>
        </div>
      `).join('');
      lucide.createIcons();
    }

    function addTodoToCurrentDate() {
      const input = document.getElementById('newTodoInput');
      const text = input.value.trim();
      if (!text) return;

      if (!plannerState.days[selectedDateStr]) {
        plannerState.days[selectedDateStr] = { priority: '', todos: [], notes: '' };
      }
      if (!plannerState.days[selectedDateStr].todos) {
        plannerState.days[selectedDateStr].todos = [];
      }

      plannerState.days[selectedDateStr].todos.push({ text: text, done: false });
      input.value = '';
      loadDailyPanel(selectedDateStr);
      renderCalendar();
      renderYearHeatmap();
      triggerAutoSave();
    }

    function toggleTodoDone(idx) {
      if (plannerState.days[selectedDateStr]?.todos[idx]) {
        plannerState.days[selectedDateStr].todos[idx].done = !plannerState.days[selectedDateStr].todos[idx].done;
        loadDailyPanel(selectedDateStr);
        renderYearHeatmap();
        triggerAutoSave();
      }
    }

    function updateTodoText(idx, val) {
      if (plannerState.days[selectedDateStr]?.todos[idx]) {
        plannerState.days[selectedDateStr].todos[idx].text = val;
        triggerAutoSave();
      }
    }

    function deleteTodoItem(idx) {
      if (plannerState.days[selectedDateStr]?.todos[idx]) {
        plannerState.days[selectedDateStr].todos.splice(idx, 1);
        loadDailyPanel(selectedDateStr);
        renderCalendar();
        renderYearHeatmap();
        triggerAutoSave();
      }
    }

    function saveCurrentDayData() {
      if (!plannerState.days[selectedDateStr]) {
        plannerState.days[selectedDateStr] = { priority: '', todos: [], notes: '' };
      }
      plannerState.days[selectedDateStr].priority = document.getElementById('dailyPriorityInput').value;
      plannerState.days[selectedDateStr].notes = document.getElementById('dailyNotesInput').value;
      renderCalendar();
      renderYearHeatmap();
      triggerAutoSave();
    }

    // ==========================================
    // 영속성 관리 (LocalStorage & Auto-Save)
    // ==========================================
    function triggerAutoSave() {
      const indicator = document.getElementById('saveStatusText');
      if (indicator) indicator.innerText = '저장 중...';

      clearTimeout(autoSaveTimer);
      autoSaveTimer = setTimeout(() => {
        saveCompassData();
        saveRocksAndRetroData();
        localStorage.setItem(STORAGE_KEY, JSON.stringify(plannerState));
        if (indicator) indicator.innerText = '자동 저장됨';
      }, 400);
    }

    function loadStateFromStorage() {
      try {
        const raw = localStorage.getItem(STORAGE_KEY);
        if (raw) {
          const parsed = JSON.parse(raw);
          plannerState = Object.assign(plannerState, parsed);
        }
      } catch (e) {
        console.error("Failed to load planner storage:", e);
      }
    }

    function exportPlannerData() {
      saveCompassData();
      saveRocksAndRetroData();
      const jsonStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(plannerState, null, 2));
      const a = document.createElement('a');
      a.href = jsonStr;
      a.download = `SETUPOD_2026_Planner_Backup_${selectedDateStr}.json`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      showToast("플래너 전체 데이터(JSON)가 백업되었습니다!");
    }

    function importPlannerData(event) {
      const file = event.target.files[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = function(e) {
        try {
          const imported = JSON.parse(e.target.result);
          if (imported && (imported.themeOfYear !== undefined || imported.quarters)) {
            plannerState = imported;
            localStorage.setItem(STORAGE_KEY, JSON.stringify(plannerState));
            if (plannerState.themeSkin) switchThemeSkin(plannerState.themeSkin);
            loadCompassData();
            renderQuarterView();
            renderCalendar();
            renderYearHeatmap();
            loadDailyPanel(selectedDateStr);
            showToast("플래너 데이터를 성공적으로 불러왔습니다!");
          } else {
            showToast("올바른 플래너 백업 파일이 아닙니다.");
          }
        } catch (err) {
          showToast("JSON 파일 읽기 오류가 발생했습니다.");
        }
      };
      reader.readAsText(file);
    }

    function showToast(msg) {
      const toast = document.getElementById('toastMsg');
      document.getElementById('toastText').innerText = msg;
      toast.classList.add('show');
      setTimeout(() => toast.classList.remove('show'), 2400);
    }

    function escapeHtml(str) {
      if (!str) return '';
      return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
    }

    // ==========================================
    // 💎 시크릿 볼트 (Executive Secret Vault) 로직
    // ==========================================
    function filterVault(category, btn) {
      document.querySelectorAll('.vault-filter-btn').forEach(b => b.classList.remove('active'));
      if (btn) btn.classList.add('active');

      const cards = document.querySelectorAll('.vault-card');
      cards.forEach(card => {
        if (category === 'all' || card.getAttribute('data-cat') === category) {
          card.style.display = 'flex';
        } else {
          card.style.display = 'none';
        }
      });
    }

    function copyVaultText(elementId, label) {
      const el = document.getElementById(elementId);
      if (!el) return;
      const text = el.innerText || el.textContent;
      navigator.clipboard.writeText(text).then(() => {
        showToast(`📋 [${label}] 클립보드에 복사되었습니다!`);
      }).catch(err => {
        const ta = document.createElement('textarea');
        ta.value = text;
        document.body.appendChild(ta);
        ta.select();
        document.execCommand('copy');
        document.body.removeChild(ta);
        showToast(`📋 [${label}] 복사 완료!`);
      });
    }

    function exportToNotionMarkdown() {
      const p = plannerState;
      const theme = p.themeOfYear || '미입력';

      let md = `# 🧭 SETUPOD 2026 비즈니스 실행 플래너\n\n`;
      md += `> 💡 **2026 올해의 핵심 테마**: ${theme}\n`;
      md += `> 📅 **데이터 생성일**: ${new Date().toLocaleDateString('ko-KR')}\n\n`;

      md += `## 🎯 5대 핵심 영역 (Life Compass)\n\n`;
      md += `| 영역 | 2026 연간 목표 | 핵심 성공 지표 (KPI) | 매일의 실행 행동 |\n`;
      md += `| :--- | :--- | :--- | :--- |\n`;

      const areaNames = {
        area1: '💼 사업 & 커리어 (Business)',
        area2: '💰 재정 & 자산 (Wealth)',
        area3: '⚡ 건강 & 에너지 (Vitality)',
        area4: '🤝 관계 & 네트워크 (Network)',
        area5: '🧠 학습 & 지혜 (Wisdom)'
      };

      for (let i = 1; i <= 5; i++) {
        const a = p.areas[`area${i}`] || {};
        md += `| ${areaNames[`area${i}`]} | ${a.goal || '-'} | ${a.metric || '-'} | ${a.action || '-'} |\n`;
      }

      md += `\n## 🏔️ 1분기 3대 핵심 과제 (Big Rocks)\n\n`;
      const q1Rocks = p.bigRocks['Q1'] || [];
      if (q1Rocks.length > 0) {
        q1Rocks.forEach((r, idx) => {
          md += `${idx + 1}. **${r.title || '과제 ' + (idx+1)}**\n`;
          md += `   - 핵심 성과 (KR): ${r.kr || '-'}\n`;
          md += `   - 마감 일정: ${r.deadline || '-'}\n\n`;
        });
      } else {
        md += `- 등록된 1분기 핵심 과제가 없습니다.\n\n`;
      }

      md += `## 🚀 1분기 프로젝트 트래커\n\n`;
      const q1Projects = p.projects['Q1'] || [];
      if (q1Projects.length > 0) {
        q1Projects.forEach(proj => {
          const statusIcon = proj.status === 'done' ? '✅ 완료' : (proj.status === 'ongoing' ? '⚡ 진행중' : '⏳ 대기');
          md += `- [${statusIcon}] **${proj.title || '프로젝트'}** (${proj.period || '-'} / 담당: ${proj.owner || '-'} / 진척도: ${proj.progress || 0}%)\n`;
        });
      } else {
        md += `- 등록된 1분기 프로젝트가 없습니다.\n`;
      }

      md += `\n---\n*Exported seamlessly from [SETUPOD 2026 PRO OS](https://setupod.com/planner)*\n`;

      navigator.clipboard.writeText(md).then(() => {
        showToast('🎉 내 플래너 전체가 Notion / Obsidian 마크다운으로 복사되었습니다! 노션에 바로 붙여넣으세요.');
      }).catch(() => {
        showToast('마크다운 클립보드 복사에 실패했습니다.');
      });
    }

    // 초기화
    window.addEventListener('DOMContentLoaded', () => {
      loadStateFromStorage();
      if (plannerState.themeSkin) switchThemeSkin(plannerState.themeSkin);
      loadCompassData();
      renderQuarterView();
      renderCalendar();
      renderYearHeatmap();
      loadDailyPanel(selectedDateStr);
      lucide.createIcons();
    });


    if (window.MazaTelemetry) {
      window.MazaTelemetry.init({ podId: 'planner' });
    }
